INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation, created_at) VALUES ('mcq_te_bc6d30696f3feafd', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_synonyms', 'Synonym: Shakespeare is a GIANT among all English literary writers.', '{"A":"Significant","B":"Great","C":"Huge","D":"Both B and C"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Here “giant” is used figuratively to mean a very great or important person in a field.Giant means ایک فیلڈ میں ایک بہت بڑا یا اہم شخصGreat means ایک فیلڈ میں ایک بہت بڑا یا اہم شخصHuge means بہت بڑاLast verified on 06-03-2026', 1790961782);
