INSERT OR REPLACE INTO mcq (id, user_id, subject_id, question, options, correct, explanation, created_at) VALUES ('mcq_te_e2a07433e16372ef', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_eng_synonyms', 'Synonym: I would go MAD. If I received a billion rupees.', '{"A":"Beside oneself with joy","B":"Insane","C":"Wild and excited","D":"Both A and B"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Go mad (informal expression) can mean becoming extremely excited or overwhelmed with happiness.Mad means پاگلBeside oneself with joy means خوشی کے ساتھ اپنے آپ کے پاسInsane means پاگلLast verified on 10-03-2026', 1790961782);
